export const BODY: string = "\n<p>لقطة PNG قد تزن عشر مرات أكثر من الصورة نفسها كـJPG. تحويلها يستغرق ثوانٍ، ويوفر مساحة هائلة.</p>\n<p>الجزء الوحيد المعقد هو الشفافية. JPG لا يستطيع حفظ بكسلات شفافة، لذلك يجب ملؤها بلون تختاره.</p>\n<p>يمر هذا الدليل بكل خطوة، لتخرج أول تحويلة نظيفة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: افحص ما إذا كانت هناك شفافية</h2>\n<p>قبل أن تبدأ، افحص ما إذا كانت هناك شفافية: افتح PNG وتحقق مما إذا كانت له خلفية شفافة. إذا كان كذلك، فستحتاج إلى اختيار لون تعبئة.</p>\n<p>إذا كانت الصورة مستطيلة كاملة دون شفافية، فالتحويل مباشر. لا حاجة إلى التفكير في لون التعبئة.</p>\n<h2 id=\"step-1-open-tool\">الخطوة 1: افتح أداة PNG إلى JPG</h2>\n<p>افتح <a href=\"/ar/tahwil-png-ila-jpg/\">أداة PNG إلى JPG</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصور إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورك خاصة طوال العملية.</p>\n<h2 id=\"step-2-upload\">الخطوة 2: ارفع ملفات PNG</h2>\n<p>ارفع ملفات PNG: أسقطها في منطقة الرفع أو اخترها من جهازك. تُقبل ملفات PNG بأي حجم معقول.</p>\n<p>إذا رفعت عدة ملفات، فستظهر كل واحدة في قائمة. يمكنك تحويلها كلها دفعة واحدة بإعدادات موحدة.</p>\n<h2 id=\"step-3-matte-colour\">الخطوة 3: اختر لون التعبئة</h2>\n<p>اختر لون التعبئة: أبيض لمعظم الحالات، وأسود للخلفيات الداكنة. اللون يملأ المناطق الشفافة في الصورة.</p>\n<p>إذا لم تكن متأكدًا، فاختر الأبيض. إنه الخيار الآمن لمعظم الوجهات، من البريد الإلكتروني إلى المواقع.</p>\n<h2 id=\"step-4-quality\">الخطوة 4: اضبط منزلق الجودة</h2>\n<p>اضبط منزلق الجودة: جودة 85 مناسبة لمعظم الصور، و90 للقطات النصية. جودة 95 للصور المهمة التي تحتاج إلى أقصى حدة.</p>\n<p>لا تستخدم جودة أقل من 80 للقطات فيها نصوص. النص يضبب بسرعة عند الجودة المنخفضة.</p>\n<h2 id=\"step-5-convert-preview\">الخطوة 5: حوّل وراجع النتيجة</h2>\n<p>حوّل وراجع النتيجة: اضغط زر التحويل وقارن النتيجة بالأصل. تأكد من أن النص حاد والألوان صحيحة ولون التعبئة مناسب.</p>\n<p>إذا بدت النتيجة جيدة، فهي جاهزة. وإذا كان لون التعبئة خاطئًا، فأعد التحويل بلون مختلف.</p>\n<h2 id=\"step-6-download\">الخطوة 6: نزّل ملفات JPG</h2>\n<p>نزّل ملفات JPG: اضغط زر التنزيل واحفظ الملفات في مجلد جديد. إذا كانت عدة ملفات، فستنزّل كملف ZIP واحد.</p>\n<p>فك ضغط الملف وراجع النتائج. تحقق من أن كل ملف موجود ويبدو صحيحًا.</p>\n<ol>\n<li>ارفع ملفات PNG.</li>\n<li>اختر لون التعبئة.</li>\n<li>اضبط الجودة.</li>\n<li>نزّل ملفات JPG.</li>\n</ol>\n<h2 id=\"converting-screenshots\">كيف تحوّل اللقطات بالطريقة الصحيحة؟</h2>\n<p>لتحويل اللقطات بالطريقة الصحيحة، استخدم جودة 90 ولون تعبئة أبيض. اللقطات تحتوي على نصوص تحتاج إلى حدة عالية.</p>\n<p>راجع عينة من النتائج قبل الاعتماد على الدفعة كلها. إذا كان النص حادًا في العينة، فغالبًا بقية اللقطات بنفس الجودة.</p>\n<h2 id=\"converting-a-batch\">كيف تحوّل دفعة من اللقطات؟</h2>\n<p>لتحويل دفعة من اللقطات، ارفع كل اللقطات وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>سمِّ المجلد حسب المشروع بعد التنزيل. التنظيم الجيد يسهّل العثور على اللقطات لاحقًا.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>لحل المشاكل الشائعة، افحص السبب أولًا. النص الضبابي يعني جودة منخفضة، ولون التعبئة الخاطئ يعني اختيارًا غير مناسب.</p>\n<p>أعد التحويل من PNG الأصلي بإعدادات مختلفة. لا تعيد التحويل من النسخة المحوّلة، لأن كل جولة تضيف ضررًا.</p>\n<h2 id=\"mobile-tips\">نصائح للهواتف والأجهزة اللوحية</h2>\n<p>نصائح للهواتف والأجهزة اللوحية: افتح الأداة في المتصفح وارفع الصور من معرضك. التحويل يعمل على الهاتف دون تثبيت أي تطبيق.</p>\n<p>للدفعات الكبيرة على الهاتف، قسّمها إلى مجموعات صغيرة. المجموعات الصغيرة أسرع وأقل عرضة للفشل.</p>\n<h2 id=\"mac-screenshots\">كيف تحوّل لقطات ماك؟</h2>\n<p>لتحويل لقطات ماك، افتح الأداة في متصفحك وارفع اللقطات من مجلد سطح المكتب. لقطات ماك تُحفظ كـPNG افتراضيًا.</p>\n<p>استخدم جودة 90 للقطات ماك. النص في واجهة ماك دقيق، والجودة العالية تحافظ على حدته.</p>\n<h2 id=\"windows-screenshots\">كيف تحوّل لقطات ويندوز؟</h2>\n<p>لتحويل لقطات ويندوز، افتح الأداة في متصفحك وارفع اللقطات من مجلد الصور. لقطات ويندوز تُحفظ كـPNG افتراضيًا.</p>\n<p>استخدم جودة 90 للقطات ويندوز. النص في واجهة ويندوز يحتاج إلى حدة عالية ليبقى مقروءًا.</p>\n<h2 id=\"phone-screenshots\">كيف تحوّل لقطات الهاتف؟</h2>\n<p>لتحويل لقطات الهاتف، افتح الأداة في متصفح هاتفك وارفع اللقطات من معرضك. لقطات الهاتف تُحفظ كـPNG غالبًا.</p>\n<p>استخدم جودة 85 للقطات الهاتف. الشاشات الصغيرة لا تحتاج إلى جودة قصوى، والملف الأصغر يرسل أسرع.</p>\n<h2 id=\"design-mockups\">كيف تحوّل نماذج التصميم؟</h2>\n<p>لتحويل نماذج التصميم، حوّلها إلى JPG للمشاركة مع العملاء. النماذج كـJPG أصغر وأسهل في الإرسال.</p>\n<p>احتفظ بالنسخ PNG الأصلية للتحرير. النموذج النهائي JPG، لكن نسخة العمل تبقى PNG.</p>\n<h2 id=\"images-for-presentation\">كيف تحوّل صورًا لعرض تقديمي؟</h2>\n<p>لتحويل صور لعرض تقديمي، حوّلها إلى JPG لتقليل حجم ملف العرض. العروض الكبيرة بطيئة في الفتح والمشاركة.</p>\n<p>استخدم جودة 85 لصور العروض. الجودة كافية للشاشة الكبيرة، والملف الأصغر يجعل العرض أسرع.</p>\n<h2 id=\"images-for-whatsapp-group\">كيف تحوّل صورًا لمجموعة واتساب؟</h2>\n<p>لتحويل صور لمجموعة واتساب، حوّلها إلى JPG قبل الإرسال. الملف الأصغر يرسل أسرع ويستهلك بيانات أقل.</p>\n<p>وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-png-ila-jpg/\">الدليل الكامل لتحويل PNG إلى JPG</a> و<a href=\"/ar/blog/png-ila-jpg-hajm-al-malaf-wa-al-jawda/\">PNG إلى JPG: حجم الملف والجودة</a>، أو حوّل إلى WebP باستخدام <a href=\"/ar/tahwil-png-ila-webp/\">محول PNG إلى WebP</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما لون التعبئة الذي أختاره لملف PNG فيه شفافية؟","answer":"اختر لونًا يطابق خلفية الوجهة: أبيض لمعظم الحالات، وأسود للخلفيات الداكنة. اللون الخاطئ يجعل الشعار يبدو غريبًا."},{"question":"هل يمكنني تحويل لقطة PNG إلى JPG دون تضبيب النص؟","answer":"نعم، استخدم جودة 90 أو أعلى للقطات النصية. النص يبقى حادًا وواضحًا عند الجودة العالية، ويضبب فقط عند الجودة المنخفضة."},{"question":"كم ملف PNG يمكنني تحويله دفعة واحدة؟","answer":"يمكنك تحويل حتى 20 ملفًا دفعة واحدة. ارفعها كلها وحوّلها بإعدادات موحدة ونزّلها كملف ZIP واحد."},{"question":"لماذا أصبح ملف JPG المحوّل أكبر من PNG الأصلي؟","answer":"لأن PNG يضغط الرسوم البسيطة جيدًا أصلًا، بينما JPG يضيف بيانات ضغط معقدة. هذا نادر، ويحدث غالبًا مع الرسوم البسيطة ذات الألوان القليلة."},{"question":"هل تحويل PNG إلى JPG يزيل الخلفية؟","answer":"لا، التحويل لا يزيل الخلفية. البكسلات الشفافة تُملأ بلون التعبئة، والخلفية الصلبة تبقى كما هي. لإزالة الخلفية، تحتاج إلى أداة إزالة خلفية."},{"question":"هل يمكنني تغيير لون التعبئة بعد التحويل؟","answer":"لا، لا يمكن تغيير لون التعبئة بعد التحويل. أعد التحويل من PNG الأصلي بلون تعبئة مختلف."}];
